function AddTable($lines, $widths) { $s = $script:pos; $r = $doc.Range($s, $s); $r.InsertAfter(($lines -join "`r") + "`r"); $rr = $doc.Range($s, $r.End); $rr.Style = 'Normal'; $rr.Font.Size = 9; $rr.Font.Bold = 0; $rr.ParagraphFormat.Alignment = 0; $rr.ParagraphFormat.SpaceBefore = 0; $rr.ParagraphFormat.SpaceAfter = 0; $tb = $rr.ConvertToTable(1); $tb.Borders.Enable = 1; $tb.Rows.Item(1).Range.Font.Bold = 1; $tb.Rows.Item(1).Shading.BackgroundPatternColor = 15983321; $tb.Rows.Item(1).HeadingFormat = -1; $tb.Rows.AllowBreakAcrossPages = 0; $tb.AutoFitBehavior(2); $script:pos = $tb.Range.End }
