AddTable $vl; AddText ('Table 6.13  Validation suite on the second machine (' + ($valRows | Where-Object { $_[1] -eq 'PASS' }).Count + ' of ' + $valRows.Count + ' checks passed)') 'cap'
$nv = @("Contribution`tClaim recomputed from results/*.jsonl`tComputed`tChecks", "1 SilentBench, HBW/MTTC`tGuard off: wrong answers (7 silent faults, 10 trials each); full guard (G4)`t100 % wrong, 0 detected; G4 0 % wrong over 70 trials; HBW 30 s vs 0 s`t11/11", "2 Probe design`tReadiness alone / readiness + liveness / partial vs strict`t91.7 % failed, never restored; 36.4 s; 0 % vs 80.7 % failed`t5/5", "3 Compound faults`tBit flip + delay: E4 / G4 / H4`t100 % wrong; 0 % wrong, p95 1615 ms; 0 % wrong, p95 768 ms`t5/5", "4 Cost-coverage`tRange, z-score, envelope vs golden; cost per check`t0 %, 12.3 % false alarms, 2.5 % vs 100 %; 182 ms vs 0.081 ms`t4/4", "5 Quality-aware recovery`tNo operator / rules / bandit v1 / bandit v2`t0/20; 20/20 (23.6 s); 5/20; 20/20 (21.6 s)`t6/6", "6 Deadline-aware degradation`tDelay fault failed requests G4 vs H4`t96.8 % vs 0 %; 94 % valid degraded answers`t3/3", "Total`tvalidation/validate_novelty.py (results/novelty_validation.txt)`tall values match the report`t34/34")
AddTable $nv; AddText 'Table 6.14  Independent recomputation of the six contributions from the raw result files' 'cap'
AddText '6.11.2  Completion of SilentBench for the golden-output configuration' 'h5'
AddText 'Table 6.2 originally had five trials in the G4 columns of five faults. Trials 6 to 10 of these faults (corrupt, scaler, flat-line, unit change, stale) were executed on 22 October 2026 on the second machine with the same protocol (5 requests per second, 15 s warm-up, 30 s fault window, 10 s heal window, operator switched off), 25 new trials in total. The healthy baseline was 100 percent correct in every new trial. The inference image was rebuilt from the repository (tag :9) instead of the original :10; the code is the repository state. All 70 silent-fault trials of G4 (7 faults x 10) served 0 percent wrong answers; for zero wrong answers in 10 trials the exact one-sided 95 percent upper bound is 25.9 percent. The rows are appended to results/silentbench.jsonl (357 rows).' 'body'
$gl = @("Fault`tG4 trials`tWrong %`tCorrect %`tFallback %`tDegraded %`tFailed %`tFisher p vs C4`t95 % upper bound (0 wrong)"); foreach ($g in $g4) { $gl += ($g -join "`t") }
AddTable $gl; AddText 'Table 6.15  G4 (golden check) after completion to ten trials per fault: mean share of responses in the 30 s fault window' 'cap'
AddText '6.11.3  Live screenshots of the running system' 'h5'
AddText 'The following screenshots were taken on 22 October 2026 from the running system: the standalone Climate application (SARIMA, Figures 6.18 to 6.25), the DevOps version served from Kubernetes with SARIMA and LSTM (Figures 6.26 to 6.29, including the degraded-mode banner after an injected silent fault), the inference API (Figures 6.30 to 6.32), the live Grafana dashboard with a bit-flip fault injected (Figure 6.33) and Prometheus queries (Figures 6.34 to 6.36). No image is a mock-up.' 'body'
$figs = @( @('A01_climate_home','Home page of the standalone Climate application (corrected CES formula and thresholds)'), @('A02_climate_dashboard','Dashboard of the standalone Climate application (SARIMA 6-month forecast)'), @('A03_climate_predict','Prediction input form'), @('A04_climate_result_extreme','Result page for 300 mm, 27 C, 85 percent: CES 2.21, Extreme Flood/Heat'), @('A05_climate_result_drought','Result page for 0 mm, 18 C, 45 percent: CES -1.755, Extreme Drought/Cold with direction label'), @('A06_climate_xai','Explainable-AI page'), @('A07_climate_analysis','Historical analysis gallery'), @('A08_climate_history','Prediction history'),
 @('B01_k8s_home','Home page of the DevOps version served from Kubernetes (corrected text)'), @('B02_k8s_dashboard_healthy','Dashboard served from Kubernetes with healthy models (LSTM tier)'), @('B03_k8s_lstm_result','LSTM result page with real LSTM forecasts'), @('B04_k8s_dashboard_DEGRADED_after_silent_fault','Dashboard after an injected silent fault: "Forecast served in degraded mode (tier: climatology)"'),
 @('C01_api_health_semantic','Inference API /health/semantic: both models valid, golden deviation 0.0'), @('C02_api_predict_lstm_tier','Inference API /predict: forecast served from the LSTM tier'), @('C03_api_slo','Inference API /slo: correctness SLI with Wilson lower bound'),
