function AddAfter($anchorText, $lines) { for ($i = 1; $i -le 420; $i++) { $pp = $doc.Paragraphs.Item($i); if ($pp.Range.Text.Trim() -like "$anchorText*") { if ($pp.Range.Information(12)) { $tb = $pp.Range.Tables.Item(1); $ri = $pp.Range.Cells.Item(1).RowIndex; foreach ($ln in $lines) { $ri++; if ($ri -le $tb.Rows.Count) { $nr = $tb.Rows.Add($tb.Rows.Item($ri)) } else { $nr = $tb.Rows.Add() }; $nr.Cells.Item(1).Range.Text = $ln } } else { $cur = $pp; foreach ($ln in $lines) { $cur.Range.InsertParagraphAfter(); $cur = $cur.Next(); $r = $cur.Range; [void]$r.MoveEnd(1, -1); $r.Text = $ln } }; return } } }
